<?php
function acSheetRows(array $r):array{if($r['kind']==='reassessment'){$rows=[];foreach($r['entries']as $v){$exam=null;foreach($r['metadata']['components']as $i=>$c)if($c['type']==='ESE')$exam=$v['marks'][$i];$rows[]=[$v['student_id'],$v['student_name'],$exam];}return $rows;}$rows=[];foreach($r['entries']as $v)$rows[]=$r['kind']==='attendance'?[$v['date'],$v['student_id'],$v['student_name'],$v['classroom'],$v['class_type'],...array_values($v['periods'])]:[$v['student_id'],$v['student_name'],...$v['marks']];return $rows;}
function acDownload(?array $u):never{
 acAssert(acAccess($u)&&acReady(),'Sign in to access Academic downloads.');$mode=$_GET['mode']??'template';
 if($mode==='report'){
  acAssert(acReportViewer($u),'Exam Cell, PL, DAA or Admin access required.');acAssert(!empty($_GET['programme'])&&!empty($_GET['academic_year'])&&!empty($_GET['study_year'])&&!empty($_GET['semester']),'Select programme, academic year, year and semester in Academic reports before exporting.');
  $records=acReportRecords($u,$_GET);$book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$summary=$book->getActiveSheet();$summary->setTitle('Read me');$summary->setCellValue('A1','Academic reports · Generated '.now().' (Bhutan time)');$summary->setCellValue('A2','Submitted records only. PL scope is their department. Latest submitted re-assessment updates consolidated results; original records are retained.');$summary->setCellValue('A3','Attendance: regular + extra present hours / fixed DPD contact hours, capped at 100%. Extra hours do not increase the denominator.');$summary->setCellValue('A4','Overall = equal-weight average of available submitted modules only; NOT an official final grade. Missing marks remain blank.');$summary->getColumnDimension('A')->setWidth(125);
  $index=1;foreach(acConsolidate($records)as $label=>$g){$sheet=$book->createSheet();$sheet->setTitle('Marks '.$index++);$headers=['Student Name','Student ID'];foreach($g['modules']as $r)foreach(['CA','ESE','Total','Result']as $suffix)$headers[]=$r['module_code'].' '.$suffix;$headers[]='Available-module average (%)';$headers[]='Coverage / review';$rows=[];foreach($g['students']as $s){$row=[$s['name'],$s['id']];foreach($g['modules']as $id=>$r){$m=$s['marks'][$id]??null;$row[]=$m['ca']??null;$row[]=$m?($m['ese']??'N/A'):null;$row[]=$m['total']??null;$row[]=($m['result']??'Missing').(isset($m['reassessment_id'])?' · RA #'.$m['reassessment_id']:'');}$row[]=$s['average'];$row[]=count($s['marks']).'/'.count($g['modules']).' submitted modules'.($s['name_conflict']?' · Name mismatch':'');$rows[]=$row;}acWriteSheet($sheet,$headers,$rows,$label);
   $sheet->insertNewRowBefore(3,1);$sheet->setAutoFilter('');$sheet->freezePane('C5');
   foreach([1,2,count($headers)-1,count($headers)] as $col){$letter=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($col);$value=$sheet->getCell($letter.'4')->getValue();$sheet->setCellValueExplicit($letter.'3',$value,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);$sheet->setCellValue($letter.'4',null);$sheet->mergeCells($letter.'3:'.$letter.'4');}
   $col=3;foreach($g['modules'] as $module){$sheet->setCellValueExplicit([$col,3],$module['module_code'],\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);$sheet->mergeCells([$col,3,$col+3,3]);foreach(['CA','ESE','Total','Result'] as $offset=>$heading)$sheet->setCellValue([$col+$offset,4],$heading);$col+=4;}
   $last=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(count($headers));$end=4+count($rows);
   $sheet->getStyle('A3:'.$last.$end)->getBorders()->getAllBorders()->setBorderStyle('thin')->getColor()->setARGB('FF9CB1C5');
   $sheet->getStyle('A3:'.$last.'4')->getFill()->setFillType('solid')->getStartColor()->setARGB('FF164D72');$sheet->getStyle('A3:'.$last.'4')->getFont()->setBold(true)->getColor()->setARGB('FFFFFFFF');$sheet->getStyle('A3:'.$last.'4')->getAlignment()->setHorizontal('center')->setVertical('center')->setWrapText(true);
   $sheet->getRowDimension(3)->setRowHeight(30);$sheet->getRowDimension(4)->setRowHeight(30);
   for($row=5;$row<=$end;$row++){if($row%2===0)$sheet->getStyle('A'.$row.':'.$last.$row)->getFill()->setFillType('solid')->getStartColor()->setARGB('FFF2F6FB');$sheet->getRowDimension($row)->setRowHeight(26);}
   $sheet->getPageSetup()->setOrientation('landscape')->setFitToWidth(1)->setFitToHeight(0)->setRowsToRepeatAtTopByStartAndEnd(3,4);
}
  $att=[];$re=[];foreach($records as $r){if($r['kind']==='attendance'){$report=acAttendance($r);foreach($report['students']as $s)$att[]=[count($att)+1,$r['programme'],$r['academic_year'],$r['study_year'],$r['semester'],$r['section'],$r['module_code'],$s['name'],$s['id'],$r['contact_hours'],$s['recorded'],$s['present'],$s['absent'],$s['extra_present'],$s['percentage'],$s['recorded_percentage'],saEligibility($r,$s)];}elseif($r['kind']==='reassessment')foreach($r['entries']as $v){$m=acMarks($r,$v);$re[]=[$r['programme'],$r['academic_year'],$r['study_year'],$r['semester'],$r['section'],$r['module_code'],$r['metadata']['attempt'],$r['metadata']['original_id'],$v['student_name'],$v['student_id'],$m['ca'],$m['ese']??'N/A',$m['raw_total'],$m['total'],$m['result'],'CA retained; successful re-assessment capped at 50'];}}
  if($att)acWriteSheet($book->createSheet()->setTitle('Attendance'),['Sl. No.','Programme','Academic Year','Year','Semester','Section','Module','Student Name','Student ID','DPD hours','Recorded hours','Present','Absent','Extra class','Attendance % (DPD)','Recorded-session %','Remarks'],$att);
  if($re)acWriteSheet($book->createSheet()->setTitle('Re-assessment'),['Programme','Academic Year','Year','Semester','Section','Module','Attempt','Original receipt','Student Name','Student ID','CA','ESE','Calculated total','Capped final','Result','Policy'],$re);
  acAudit($u,0,'Report exported',['filters'=>array_intersect_key($_GET,array_flip(['department','programme','academic_year','study_year','semester','section','kind']))]);$name='academic-report';
 }else{
  $r=acGet($u,(int)($_GET['id']??0));if($r['kind']==='attendance')saDownload($u);$headers=acHeaders($r);$rows=$mode==='draft'?acSheetRows($r):[];
  if(($_GET['format']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="academic-'.$r['kind'].'-template.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");foreach([$headers,...$rows]as $row)fputcsv($f,array_map(fn($v)=>preg_match('/^[=+@\-\t\r]/',(string)$v)?"'".$v:$v,$row));exit;}
  $book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();acWriteSheet($book->getActiveSheet()->setTitle('Data'),$headers,$rows);$instructions=$book->createSheet()->setTitle('Instructions');$lines=[$r['module_code'].' · '.$r['module_name'],$r['programme'].' · '.$r['academic_year'].' · Year '.$r['study_year'].' · Semester '.$r['semester'].' · Section '.$r['section'],'DPD contact hours: '.$r['contact_hours'].' · Tutor receipt: #'.$r['id'],'Fill the Data sheet. Do not rename headers. Keep Student IDs as text (including leading zeroes).','Upload values only, no formulas. Maximum 5,000 rows. Re-upload to amend your draft before final submission.'];
  if($r['kind']==='attendance')$lines=array_merge($lines,['One student/date/class type per row. Dates: YYYY-MM-DD or DD-MM-YYYY. Repeat students for each teaching date.','Class Type: Regular or Extra. P = present; A = absent. Leave unused periods blank for every student.','Each listed period is one hour; breaks are excluded. Assembly/seminar periods are unused unless an actual module class took place.','Before final submission every student needs P/A for every recorded session. Extra attendance counts as make-up towards fixed DPD hours, capped at 100%.','Merge adds new rows and replaces matching Student ID + Date + Class Type rows; Replace replaces the entire draft.']);elseif($r['kind']==='reassessment'){$lines[]='Enter the new ESE raw mark only. Original CA is retained; a passing result is capped at 50. Student ID and name must match the original submission.';}else foreach($r['metadata']['components']as $c)$lines[]=$c['name'].': maximum '.$c['max'].'; weight '.$c['weight'].'%; '.$c['type'].'. Blank marks are incomplete, not zero.';
  foreach($lines as $i=>$line)$instructions->setCellValueExplicit([1,$i+1],$line,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);$instructions->getColumnDimension('A')->setWidth(125);$instructions->getStyle('A1:A20')->getAlignment()->setWrapText(true);$book->setActiveSheetIndex(0);$name='academic-'.$r['kind'].'-'.$mode;
 }
 header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$name.'.xlsx"');(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');exit;
}
function acWriteSheet($sheet,array $headers,array $rows,string $title=''):void{
 $start=$title!==''?3:1;if($title!=='')$sheet->setCellValueExplicit('A1',$title,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);
 foreach([$headers,...$rows]as $ri=>$row)foreach($row as $ci=>$v){if($v===null)continue;$sheet->setCellValueExplicit([$ci+1,$ri+$start],$v,is_int($v)||is_float($v)?\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_NUMERIC:\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);}
 $last=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(count($headers));$sheet->getStyle('A'.$start.':'.$last.$start)->getFont()->setBold(true)->getColor()->setARGB('FFFFFFFF');$sheet->getStyle('A'.$start.':'.$last.$start)->getFill()->setFillType('solid')->getStartColor()->setARGB('FF164D72');$sheet->getStyle('A'.$start.':'.$last.max($start,$start+count($rows)))->getBorders()->getAllBorders()->setBorderStyle('thin')->getColor()->setARGB('FF9CB1C5');$sheet->getStyle('A'.$start.':'.$last.$start)->getAlignment()->setWrapText(true);$sheet->getRowDimension($start)->setRowHeight(42);$sheet->freezePane('C'.($start+1));$sheet->setAutoFilter('A'.$start.':'.$last.max($start,$start+count($rows)));foreach(range(1,count($headers))as $c)$sheet->getColumnDimension(\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($c))->setWidth(24);
}
